<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $title ?? 'TokenHub' }}</title><style>:root{--b:#2563eb;--i:#17202a;--m:#718096;--l:#e6eaf0}*{box-sizing:border-box}body{margin:0;background:#f7f9fc;color:var(--i);font:14px system-ui,sans-serif}a{text-decoration:none;color:inherit}.top{height:68px;background:#fff;border-bottom:1px solid var(--l);display:flex;align-items:center;padding:0 5%;justify-content:space-between}.brand{font-size:19px;font-weight:800}.mark{display:inline-grid;place-items:center;background:var(--b);color:#fff;border-radius:7px;width:29px;height:29px;margin-right:8px}.nav{display:flex;gap:25px;color:var(--m)}.usernav{display:flex;gap:15px;align-items:center}.btn{border:0;border-radius:6px;padding:10px 15px;font-weight:700;cursor:pointer}.primary{background:var(--b);color:white}.secondary{background:#eaf2ff;color:#2456bd}.ghost{background:transparent;color:#607086}.wrap{max-width:1160px;margin:auto;padding:42px 25px}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:45px;align-items:center;padding:35px 0 65px}.eyebrow{color:var(--b);font-weight:800;text-transform:uppercase;font-size:11px;letter-spacing:1.5px}.hero h1{font-size:50px;line-height:1.06;letter-spacing:-2px;margin:14px 0}.hero p{color:var(--m);font-size:17px;line-height:1.7;max-width:560px}.hero-box{background:#101827;color:#fff;padding:26px;border-radius:11px;box-shadow:0 18px 45px #182b4d22}.code{font:13px monospace;color:#b8c8e6;line-height:1.8}.code b{color:#8ed1ff}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#fff;border:1px solid var(--l);border-radius:9px;padding:21px}.inline{display:flex;justify-content:space-between;align-items:center;gap:12px}.model-name{font-weight:800;font-size:17px}.pill{font-size:11px;background:#eaf2ff;color:#2563eb;border-radius:5px;padding:4px 7px;font-weight:700}.muted{color:var(--m)}.price{margin-top:20px;color:#526174}.price strong{font-size:19px;color:var(--i)}.section-title{display:flex;justify-content:space-between;align-items:end;margin:18px 0}.section-title h2{font-size:24px;margin:0}.auth{min-height:calc(100vh - 68px);display:grid;place-items:center}.auth-card{width:420px;background:#fff;padding:34px;border:1px solid var(--l);border-radius:11px}.auth-card h1{margin:0 0 8px;font-size:27px}.field{margin:17px 0}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:6px;color:#526174}.field input,.key-input{width:100%;border:1px solid #d9e0e9;border-radius:6px;padding:11px;font-size:14px}.alert{border-radius:7px;padding:12px 14px;margin:14px 0;background:#eaf8f1;color:#087443}.error{background:#fff1f2;color:#be123c}.dash{display:grid;grid-template-columns:200px 1fr;gap:35px}.side a{display:block;padding:11px;border-radius:7px;color:#65758b;margin-bottom:4px}.side a.active,.side a:hover{background:#eaf2ff;color:#2456bd;font-weight:700}.main h1{margin:0;font-size:28px}.statgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:25px 0}.stat{background:#fff;border:1px solid var(--l);padding:18px;border-radius:9px}.stat small{color:var(--m);display:block;margin-bottom:10px}.stat strong{font-size:25px}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;padding:13px 9px;border-bottom:1px solid var(--l)}.table th{font-size:11px;text-transform:uppercase;color:var(--m)}@media(max-width:800px){.top{padding:0 18px}.nav{display:none}.wrap{padding:28px 18px}.hero,.dash{grid-template-columns:1fr}.hero h1{font-size:40px}.grid,.statgrid{grid-template-columns:1fr}.auth-card{width:calc(100% - 30px)}} </style></head><body><header class="top"><a class="brand" href="{{ route('home') }}"><span class="mark">T</span>TokenHub</a><nav class="nav"><a href="{{ route('models') }}">Models</a><a href="{{ route('home') }}#docs">API docs</a><a href="{{ route('home') }}#pricing">Pricing</a></nav><div class="usernav">@auth<a href="{{ route('dashboard') }}">Cabinet</a><form method="post" action="{{ route('logout') }}">@csrf<button class="btn ghost">Выйти</button></form>@else<a href="{{ route('login') }}">Войти</a><a class="btn primary" href="{{ route('register') }}">Создать аккаунт</a>@endauth</div></header>@yield('content')</body></html>